using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

// Entity hierarchy for demonstrating discriminator handling
public class Vehicle
{
    public string Id { get; set; } = default!;
    public string Make { get; set; } = default!;
}

public class Car : Vehicle
{
    public int Seats { get; set; }
}

public class Truck : Vehicle
{
    public double PayloadTons { get; set; }
}

public class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=PLACEHOLDER",
            "VehicleDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Vehicle>(b =>
        {
            b.ToContainer("Vehicles");
            b.HasPartitionKey(v => v.Make);

            // EF Core 9 breaking change: The Cosmos provider now uses "$type"
            // as the discriminator property by default instead of "Discriminator".
            // For existing documents that already store "Discriminator", explicitly
            // configure the old property name to maintain backward compatibility.
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Vehicle>("Vehicle")
                .HasValue<Car>("Car")
                .HasValue<Truck>("Truck");
        });
    }
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by
    // the Cosmos provider. All queries must use async methods (ToListAsync,
    // FirstOrDefaultAsync, etc.) instead of ToList(), First(), etc.
    public async Task<List<Vehicle>> GetVehiclesAsync(CosmosDbContext db)
    {
        return await db.Vehicles.Where(v => v.Make == "Toyota").ToListAsync();
    }

    public async Task<Vehicle?> GetVehicleByIdAsync(CosmosDbContext db, string id)
    {
        return await db.Vehicles.FirstOrDefaultAsync(v => v.Id == id);
    }
}

