    // FirstOrDefaultAsync, etc.) instead of ToList(), First(), etc.
    public async Task<List<Vehicle>> GetVehiclesAsync(CosmosDbContext db)
    {
        return await db.Vehicles.Where(v => v.Make == "Toyota").ToListAsync();
    }

    public async Task<Vehicle?> GetVehicleByIdAsync(CosmosDbContext db, string id)
    {
        return await db.Vehicles.FirstOrDefaultAsync(v => v.Id == id);
    }
}

